@Component("dispositionReview-handler")
@ProcessingGroup("dispositionReview-processing-group")
public class DispositionReviewEventHandler {
	
	// core constructor
	DispositionReviewEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDispositionReviewEvent
     */
    @EventHandler
    public void handle( CreateDispositionReviewEvent event) {
        entityManager.persist(new DispositionReview(event.getDispositionReviewId(), event.getReviewDate(), event.getReviewer(), event.getNotes(), event.getRecord(), event.getRetentionSchedule(), event.getOutcome()));
    }

    /*
     * @param	event UpdateDispositionReviewEvent
     */
    @EventHandler
    public DispositionReview handle( UpdateDispositionReviewEvent event) {
    	entityManager.merge(new DispositionReview(event.getDispositionReviewId(), event.getReviewDate(), event.getReviewer(), event.getNotes(), event.getRecord(), event.getRetentionSchedule(), event.getOutcome()));
    }
    
    /*
     * @param	event DeleteDispositionReviewEvent
     */
    @EventHandler
    public void on( DeleteDispositionReviewEvent event) {
    	DispositionReview entity = new DispositionReview();
   
    	// ------------------------------------------
    	// apply the DispositionReviewId
    	// ------------------------------------------
    	entity.setDispositionReviewId( event.getDispositionReviewId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DispositionReviewRepository dispositionReviewEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DispositionReviewEventHandler.class.getName());

}
